    fn clone(&self) -> TestResult;
}

impl TestResultCl for TestResult {
    fn clone(&self) -> TestResult {
        TestResult {
            test_case: self.test_case.clone(),
            passed: self.passed,
            error_message: self.error_message.clone(),
            execution_time_ms: self.execution_time_ms
        }
    }
}

trait TestCaseCl {
    fn clone(&self) -> TestCase;
}

impl TestCaseCl for TestCase {
    fn clone(&self) -> TestCase {
        TestCase {
            test_type: self.test_type.clone(),
            intent: self.intent.clone(),
            input_data: self.input_data.clone(),
            expected_output: self.expected_output.clone(),
            description: self.description.clone()
        }
    }
}

trait TestTypeCl {
    fn clone(&self) -> TestType;
}

impl TestTypeCl for TestType {
    fn clone(&self) -> TestType {
        match self {
            TestType::Positive => TestType::Positive,
            TestType::EdgeCase => TestType::EdgeCase,
