// 20개 테스트 (Test Gen 10 + Error Analyzer 10)

use crate::phase3::test_generator::*;
use crate::phase3::error_analyzer::*;

// ===== PART A: Test Generator Tests (10개) =====

test "test_gen_compute_creation" {
    let gen = create_test_generator(IntentType::Compute);
    assert gen.total_count > 0;
}

test "test_gen_compute_count" {
    let gen = create_test_generator(IntentType::Compute);
    assert gen.total_count >= 5;
}

test "test_gen_transform_tests" {
    let gen = create_test_generator(IntentType::Transform);
    assert gen.total_count > 0;
}

test "test_gen_filter_tests" {
    let gen = create_test_generator(IntentType::Filter);
    let positive = gen.clone().get_positive_tests();
    assert positive.len() > 0;
}

test "test_gen_edge_cases" {
    let gen = create_test_generator(IntentType::Compute);
    let edge = gen.clone().get_edge_case_tests();
    assert edge.len() > 0;
}

test "test_gen_negative_tests" {
    let gen = create_test_generator(IntentType::Compute);
    let negative = gen.clone().get_negative_tests();
    assert negative.len() > 0;
}

test "test_gen_performance_tests" {
    let gen = create_test_generator(IntentType::Compute);
    let perf = gen.clone().get_performance_tests();
    assert perf.len() > 0;
}

test "test_gen_aggregate_intent" {
    let gen = create_test_generator(IntentType::Aggregate);
    assert gen.total_count > 0;
}

test "test_gen_all_intents" {
    let total = count_total_tests();
    assert total > 30;
}

test "test_gen_intent_count" {
    let compute_count = count_tests_for_intent(IntentType::Compute);
    let transform_count = count_tests_for_intent(IntentType::Transform);
    assert compute_count > 0 && transform_count > 0;
}

// ===== PART B: Error Analyzer Tests (10개) =====

test "error_analyzer_creation" {
    let analyzer = create_error_analyzer();
    assert analyzer.errors.len() == 0;
}

test "error_classification_type_mismatch" {
    let error_type = classify_error("type mismatch in function".to_string());
    match error_type {
        ErrorType::TypeMismatch => assert true,
        _ => assert false
    }
}

test "error_classification_bounds" {
    let error_type = classify_error("index out of bounds error".to_string());
    match error_type {
        ErrorType::BoundsError => assert true,
        _ => assert false
    }
}

test "error_classification_timeout" {
    let error_type = classify_error("execution timeout exceeded".to_string());
    match error_type {
        ErrorType::Timeout => assert true,
        _ => assert false
    }
}

test "error_classification_null" {
    let error_type = classify_error("null pointer dereference".to_string());
    match error_type {
        ErrorType::NullPointer => assert true,
        _ => assert false
    }
}

test "error_severity_calculation" {
    let severity = calculate_severity(ErrorType::NullPointer);
    assert severity == 9;
}

test "error_severity_performance" {
    let severity = calculate_severity(ErrorType::PerformanceIssue);
    assert severity == 5;
}

test "error_pattern_categorization" {
    let pattern = categorize_pattern("memory allocation failed".to_string());
    assert pattern == "MemoryManagement".to_string();
}

test "error_analyzer_add_result" {
    let mut analyzer = create_error_analyzer();
    let intent = Intent {
        intent_type: IntentType::Compute,
        raw_input: "test".to_string(),
        params: vec![],
        confidence: 0.9,
        matched_keywords: vec![]
    };
    let test_case = TestCase {
        test_type: TestType::Positive,
        intent,
        input_data: vec![],
        expected_output: "ok".to_string(),
        description: "test".to_string()
    };
    let result = TestResult {
        test_case,
        passed: true,
        error_message: "".to_string(),
        execution_time_ms: 100
    };
    analyzer = analyzer.add_test_result(result);
    assert analyzer.test_results.len() == 1;
}

test "error_analyzer_summary" {
    let analyzer = create_error_analyzer();
    let (total, failed, critical) = analyzer.get_error_summary();
    assert total == 0 && failed == 0 && critical == 0;
}

