// Phase 3 Week 2 Tests: Patch Generator + Verifier + Self-Healing Loop
// 30개 테스트 (Patch Gen 10 + Verifier 10 + Self-Healing 10)

use crate::phase3::test_generator::*;
use crate::phase3::error_analyzer::*;
use crate::phase3::patch_generator::*;
use crate::phase3::verifier::*;
use crate::phase3::self_healing_loop::*;

// ===== PART A: Patch Generator Tests (10개) =====

test "patch_gen_creation" {
    let gen = create_patch_generator();
    assert gen.rules.len() == 20;
}

test "patch_gen_null_pointer_rule" {
    let error = ErrorAnalysis {
        error_type: ErrorType::NullPointer,
        location: "func.rs:42".to_string(),
        message: "null pointer dereference".to_string(),
        severity: 9,
        frequency: 1,
        affected_tests: vec![]
    };

    let patches = generate_patches_for_errors(vec![error]);
    assert patches.len() > 0;
}

test "patch_gen_bounds_error_rule" {
    let error = ErrorAnalysis {
        error_type: ErrorType::BoundsError,
        location: "func.rs:50".to_string(),
        message: "index out of bounds error".to_string(),
        severity: 8,
        frequency: 1,
        affected_tests: vec![]
    };

    let patches = generate_patches_for_errors(vec![error]);
    assert patches.len() > 0;
}

test "patch_gen_type_mismatch_rule" {
    let error = ErrorAnalysis {
        error_type: ErrorType::TypeMismatch,
        location: "func.rs:60".to_string(),
        message: "type mismatch in function".to_string(),
        severity: 7,
        frequency: 1,
        affected_tests: vec![]
    };

    let patches = generate_patches_for_errors(vec![error]);
    assert patches.len() > 0;
}

test "patch_gen_division_by_zero" {
    let error = ErrorAnalysis {
        error_type: ErrorType::RuntimeError,
        location: "math.rs:10".to_string(),
        message: "division by zero".to_string(),
        severity: 8,
        frequency: 1,
        affected_tests: vec![]
    };

    let patches = generate_patches_for_errors(vec![error]);
    assert patches.len() > 0;
}

test "patch_gen_confidence_filtering" {
    let error = ErrorAnalysis {
        error_type: ErrorType::NullPointer,
        location: "func.rs:42".to_string(),
        message: "null pointer dereference".to_string(),
        severity: 9,
        frequency: 1,
        affected_tests: vec![]
    };

    let patches = generate_patches_for_errors(vec![error]);
    let high_conf = filter_patches_by_confidence(patches, 0.85);
    assert high_conf.len() > 0;
}

test "patch_gen_auto_fixable_count" {
    let errors = vec![
        ErrorAnalysis {
            error_type: ErrorType::NullPointer,
            location: "func.rs:42".to_string(),
            message: "null pointer dereference".to_string(),
            severity: 9,
            frequency: 1,
            affected_tests: vec![]
        },
        ErrorAnalysis {
            error_type: ErrorType::BoundsError,
            location: "func.rs:50".to_string(),
            message: "index out of bounds error".to_string(),
            severity: 8,
            frequency: 1,
            affected_tests: vec![]
        }
    ];

    let patches = generate_patches_for_errors(errors);
    let count = count_auto_fixable(patches);
    assert count > 0;
}

test "patch_gen_low_confidence_rejection" {
    let gen = create_patch_generator();
    assert gen.rules.len() > 0;
}

test "patch_gen_multiple_errors" {
    let errors = vec![
        ErrorAnalysis {
            error_type: ErrorType::NullPointer,
            location: "func.rs:42".to_string(),
            message: "null pointer".to_string(),
            severity: 9,
            frequency: 1,
            affected_tests: vec![]
        },
        ErrorAnalysis {
            error_type: ErrorType::PerformanceIssue,
            location: "loop.rs:100".to_string(),
            message: "execution took 5 seconds".to_string(),
            severity: 5,
            frequency: 1,
            affected_tests: vec![]
        }
    ];

    let patches = generate_patches_for_errors(errors);
    assert patches.len() == 2;
}

test "patch_gen_unmatched_error" {
    let error = ErrorAnalysis {
        error_type: ErrorType::Unknown,
        location: "unknown.rs:0".to_string(),
        message: "unknown error type xyz".to_string(),
        severity: 1,
        frequency: 1,
        affected_tests: vec![]
    };

    let patches = generate_patches_for_errors(vec![error]);
    assert patches.len() > 0;
}

// ===== PART B: Verifier Tests (10개) =====

test "verifier_creation" {
    let verifier = create_verifier();
    assert true;
}

test "verifier_confidence_score_high" {
    let score = calculate_confidence_score(5, 5, true, true, 5);
    assert score > 80.0;
}

test "verifier_confidence_score_medium" {
    let score = calculate_confidence_score(5, 4, false, false, 5);
    assert score > 50.0 && score < 80.0;
}

test "verifier_confidence_score_low" {
    let score = calculate_confidence_score(5, 2, false, false, 5);
    assert score < 50.0;
}

test "verifier_verdict_approved" {
    let verdict = determine_verdict(95.0);
    assert verdict == "APPROVED".to_string();
}

test "verifier_verdict_manual_review" {
    let verdict = determine_verdict(75.0);
    assert verdict == "MANUAL_REVIEW".to_string();
}

test "verifier_verdict_rejected" {
    let verdict = determine_verdict(50.0);
    assert verdict == "REJECTED".to_string();
}

test "verifier_test_execution_simulation" {
    let intent = Intent {
        intent_type: IntentType::Compute,
        raw_input: "test".to_string(),
        params: vec![],
        confidence: 0.9,
        matched_keywords: vec![]
    };

    let test = TestCase {
        test_type: TestType::Positive,
        intent,
        input_data: vec![],
        expected_output: "ok".to_string(),
        description: "test".to_string()
    };

    let result = simulate_test_execution(test, false);
    assert result;
}

test "verifier_count_results" {
    let results = vec![
        VerificationResult {
            patch: create_test_patch("APPROVED"),
            original_tests_pass: true,
            new_tests_pass: true,
            performance_improved: true,
            memory_improved: true,
            verdict: "APPROVED".to_string(),
            confidence_score: 95.0
        }
    ];

    let approved = count_approved_patches(results);
    assert approved == 1;
}

test "verifier_approval_rate" {
    let verifier = create_verifier();
    assert true;
}

// ===== PART C: Self-Healing Loop Tests (10개) =====

test "healing_session_creation" {
    let session = create_healing_session("test-session".to_string());
    assert session.generation == 1;
}

test "healing_loop_engine_creation" {
    let engine = create_healing_loop_engine(3, 0.75);
    assert true;
}

test "healing_generation_execution" {
    let session = run_healing_generation(IntentType::Compute, 0.0);
    assert session.tests_generated > 0;
}

test "healing_error_detection" {
    let session = run_healing_generation(IntentType::Filter, 0.0);
    assert session.errors_found > 0;
}

test "healing_patch_generation" {
    let session = run_healing_generation(IntentType::Transform, 0.0);
    assert session.patches_applied > 0;
}

test "healing_patch_approval" {
    let session = run_healing_generation(IntentType::Aggregate, 0.0);
    assert session.patches_approved >= 0;
}

test "healing_proof_score_calculation" {
    let session = run_healing_generation(IntentType::Compute, 0.5);
    assert session.proof_score >= 0.0 && session.proof_score <= 100.0;
}

test "healing_loop_termination_condition" {
    let result = should_continue_healing(0.8, 0.75, 1, 3);
    assert result == false;
}

test "healing_loop_full_cycle" {
    let report = run_self_healing_loop(IntentType::Compute);
    assert report.overall_success;
}

test "healing_statistics_collection" {
    let engine = create_healing_loop_engine(3, 0.75);
    let report = engine.run_healing_loop(IntentType::Filter);
    assert report.session.proof_score >= 0.0;
}

// ===== Helper Functions =====

fn create_test_patch(verdict: String) -> Patch {
    Patch {
        error_type: ErrorType::NullPointer,
        location: "test.rs:1".to_string(),
        original_code: "original".to_string(),
        patched_code: "patched".to_string(),
        explanation: "test patch".to_string(),
        confidence: if verdict == "APPROVED".to_string() { 0.95 } else { 0.5 }
    }
}

