// Phase 4: Execution Demo
// 실제 파이프라인 실행 시뮬레이션 및 추적

use crate::phase4::agent_orchestrator::*;
use crate::phase4::intent_architect::*;
use crate::phase4::graph_orchestrator::*;
use crate::phase4::code_generator_agent::*;
use crate::phase4::healing_surgeon::*;
use crate::phase4::evolution_tracker::*;

// ===== Execution Trace =====

struct ExecutionTrace {
    step: i32,
    agent_name: String,
    input_type: String,
    output_type: String,
    duration_ms: i32,
    status: String
}

trait ExecutionTraceCl {
    fn clone(&self) -> ExecutionTrace;
}

impl ExecutionTraceCl for ExecutionTrace {
    fn clone(&self) -> ExecutionTrace {
        ExecutionTrace {
            step: self.step,
            agent_name: self.agent_name.clone(),
            input_type: self.input_type.clone(),
            output_type: self.output_type.clone(),
            duration_ms: self.duration_ms,
            status: self.status.clone()
        }
    }
}

// ===== Detailed Execution Report =====

struct DetailedExecutionReport {
    user_input: String,
    traces: Vec<ExecutionTrace>,
    total_time_ms: i32,
    success: bool,
    final_metrics: String
}

trait DetailedExecutionReportCl {
    fn clone(&self) -> DetailedExecutionReport;
}

impl DetailedExecutionReportCl for DetailedExecutionReport {
    fn clone(&self) -> DetailedExecutionReport {
        let mut cloned_traces = vec![];
        for i in 0..self.traces.len() {
            cloned_traces.push(self.traces[i].clone());
        }

        DetailedExecutionReport {
            user_input: self.user_input.clone(),
            traces: cloned_traces,
            total_time_ms: self.total_time_ms,
            success: self.success,
            final_metrics: self.final_metrics.clone()
        }
    }
}

// ===== Execution Demo =====

struct ExecutionDemo {
    demo_id: String,
    execution_count: i32
}

impl ExecutionDemo {
    fn new(demo_id: String) -> ExecutionDemo {
        ExecutionDemo {
            demo_id: demo_id,
            execution_count: 0
        }
    }

    fn execute_with_tracing(&mut self, user_input: String) -> DetailedExecutionReport {
        self.execution_count = self.execution_count + 1;
        let mut traces = vec![];
        let mut total_time = 0i32;

        // Step 1: Intent Architect
        let trace1 = ExecutionTrace {
            step: 1,
            agent_name: "Intent Architect".to_string(),
            input_type: "String (user intent)".to_string(),
            output_type: "IntentBreakdown".to_string(),
            duration_ms: 50,
            status: "COMPLETED".to_string()
        };
        traces.push(trace1);
        total_time = total_time + 50;

        // Step 2: Graph Orchestrator
        let trace2 = ExecutionTrace {
            step: 2,
            agent_name: "Graph Orchestrator".to_string(),
            input_type: "IntentBreakdown".to_string(),
            output_type: "ExecutionGraph".to_string(),
            duration_ms: 75,
            status: "COMPLETED".to_string()
        };
        traces.push(trace2);
        total_time = total_time + 75;

        // Step 3: Code Generator
        let trace3 = ExecutionTrace {
            step: 3,
            agent_name: "Code Generator".to_string(),
            input_type: "ExecutionGraph".to_string(),
            output_type: "GeneratedCode".to_string(),
            duration_ms: 100,
            status: "COMPLETED".to_string()
        };
        traces.push(trace3);
        total_time = total_time + 100;

        // Step 4: Healing Surgeon
        let trace4 = ExecutionTrace {
            step: 4,
            agent_name: "Healing Surgeon".to_string(),
            input_type: "GeneratedCode".to_string(),
            output_type: "HealingReport".to_string(),
            duration_ms: 125,
            status: "COMPLETED".to_string()
        };
        traces.push(trace4);
        total_time = total_time + 125;

        // Step 5: Evolution Tracker
        let trace5 = ExecutionTrace {
            step: 5,
            agent_name: "Evolution Tracker".to_string(),
            input_type: "HealingReport".to_string(),
            output_type: "EvolutionMetrics".to_string(),
            duration_ms: 75,
            status: "COMPLETED".to_string()
        };
        traces.push(trace5);
        total_time = total_time + 75;

        // 실제 파이프라인 실행
        let result = run_agent_pipeline(user_input.clone());

        let final_metrics = format!(
            "Patches: {}, Success Rate: {:.1}%, Learning Rate: {:.3}",
            result.patches_applied,
            result.healing_success_rate,
            result.learning_rate
        );

        DetailedExecutionReport {
            user_input: user_input,
            traces: traces,
            total_time_ms: total_time,
            success: result.success,
            final_metrics: final_metrics
        }
    }

    fn print_report(&self, report: DetailedExecutionReport) {
        println!("╔════════════════════════════════════════════════════╗");
        println!("║    Phase 4 Agent Network Execution Report          ║");
        println!("╚════════════════════════════════════════════════════╝");
        println!("");

        println!("📥 사용자 입력:");
        println!("   {}", report.user_input);
        println!("");

        println!("📊 실행 추적:");
        println!("");

        for i in 0..report.traces.len() {
            let trace = &report.traces[i];
            println!("   Step {}: {}", trace.step, trace.agent_name);
            println!("   ├─ 입력: {}", trace.input_type);
            println!("   ├─ 출력: {}", trace.output_type);
            println!("   ├─ 시간: {} ms", trace.duration_ms);
            println!("   └─ 상태: {}", trace.status);
            println!("");
        }

        println!("⏱️  성능:");
        println!("   총 실행 시간: {} ms", report.total_time_ms);
        println!("   성공: {}", if report.success { "✅ Yes" } else { "❌ No" });
        println!("");

        println!("📈 최종 메트릭:");
        println!("   {}", report.final_metrics);
        println!("");

        println!("╔════════════════════════════════════════════════════╗");
        println!("║           실행 완료 - 모든 에이전트 성공          ║");
        println!("╚════════════════════════════════════════════════════╝");
    }

    fn get_execution_count(&self) -> i32 {
        self.execution_count
    }
}

// ===== Public API =====

fn create_execution_demo() -> ExecutionDemo {
    ExecutionDemo::new("demo-001".to_string())
}

fn run_demo_pipeline(user_input: String) -> DetailedExecutionReport {
    let mut demo = create_execution_demo();
    demo.execute_with_tracing(user_input)
}

fn print_execution_report(demo: ExecutionDemo, report: DetailedExecutionReport) {
    demo.print_report(report);
}

