// Phase 4 실제 실행 데모 테스트

use crate::phase4::execution_demo::*;

test "execution_demo_creation" {
    let demo = create_execution_demo();
    assert demo.get_execution_count() == 0;
}

test "execution_demo_basic_pipeline" {
    let report = run_demo_pipeline("더하기".to_string());
    assert report.success == true;
    assert report.traces.len() == 5;
}

test "execution_demo_all_steps_completed" {
    let report = run_demo_pipeline("테스트".to_string());
    let mut completed_count = 0i32;
    for i in 0..report.traces.len() {
        if report.traces[i].status == "COMPLETED".to_string() {
            completed_count = completed_count + 1;
        }
    }
    assert completed_count == 5;
}

test "execution_demo_timing" {
    let report = run_demo_pipeline("시간측정".to_string());
    assert report.total_time_ms > 0;
    assert report.total_time_ms < 1000;
}

test "execution_demo_trace_order" {
    let report = run_demo_pipeline("순서".to_string());
    assert report.traces[0].step == 1;
    assert report.traces[1].step == 2;
    assert report.traces[2].step == 3;
    assert report.traces[3].step == 4;
    assert report.traces[4].step == 5;
}

test "execution_demo_agent_names" {
    let report = run_demo_pipeline("에이전트".to_string());
    assert report.traces[0].agent_name == "Intent Architect".to_string();
    assert report.traces[1].agent_name == "Graph Orchestrator".to_string();
    assert report.traces[2].agent_name == "Code Generator".to_string();
    assert report.traces[3].agent_name == "Healing Surgeon".to_string();
    assert report.traces[4].agent_name == "Evolution Tracker".to_string();
}

test "execution_demo_input_output_types" {
    let report = run_demo_pipeline("타입".to_string());
    assert report.traces[0].input_type.len() > 0;
    assert report.traces[0].output_type.len() > 0;
}

test "execution_demo_metrics_present" {
    let report = run_demo_pipeline("메트릭".to_string());
    assert report.final_metrics.len() > 0;
    assert report.final_metrics.contains("Patches");
}

test "execution_demo_full_cycle" {
    let report = run_demo_pipeline("전체 사이클".to_string());
    assert report.user_input == "전체 사이클".to_string();
    assert report.success == true;
    assert report.total_time_ms > 0;
    assert report.traces.len() == 5;
