    json.push_str("\",\"version\":\"");
    json.push_str(info.version.as_str());
    json.push_str("\",\"host\":\"");
    json.push_str(info.host.as_str());
    json.push_str("\",\"port\":");
    json.push_str(&info.port.to_string());
    json.push_str(",\"environment\":\"");
    json.push_str(info.environment.as_str());
    json.push_str("\"}");
