        last_execution: "2026-03-18T12:00:00Z".to_string(),
        success_rate: 0.96f32,
        total_executions: 10i32
    });

    statuses.push(AgentStatus {
        agent_name: "evolution-tracker".to_string(),
        status: "ACTIVE".to_string(),
        last_execution: "2026-03-18T12:00:00Z".to_string(),
        success_rate: 0.99f32,
        total_executions: 10i32
    });

    statuses
}

fn update_agent_status(state: DeploymentState, agent_name: String, success: bool) -> DeploymentState {
    let mut updated_agents = vec![];

    for i in 0..state.agent_statuses.len() {
        let agent = &state.agent_statuses[i];
        if agent.agent_name == agent_name {
            let total = agent.total_executions + 1;
            let success_count = if success {
                (agent.success_rate * (agent.total_executions as f32)) as i32 + 1
            } else {
                (agent.success_rate * (agent.total_executions as f32)) as i32
            };
            let new_rate = (success_count as f32) / (total as f32);

            updated_agents.push(AgentStatus {
                agent_name: agent.agent_name.clone(),
                status: "ACTIVE".to_string(),
                last_execution: "2026-03-18T12:00:00Z".to_string(),
                success_rate: new_rate,
                total_executions: total
            });
        } else {
            updated_agents.push(agent.clone());
        }
    }

    DeploymentState {
        service_info: state.service_info.clone(),
        agent_statuses: updated_agents,
        is_healthy: state.is_healthy,
        pipeline_health: state.pipeline_health,
        total_pipeline_runs: state.total_pipeline_runs
    }
