// Phase 5: Dashboard Generator
// Dracula 테마 HTML 대시보드 생성, 실시간 모니터링 UI

use crate::phase5::metrics_api::*;
use crate::phase5::deployment_manager::*;

// ===== Dashboard Data Structures =====

struct DashboardConfig {
    title: String,
    refresh_interval_sec: i32,
    max_history_rows: i32,
    theme_bg: String,
    theme_accent: String,
    theme_pink: String,
    theme_cyan: String,
    theme_orange: String,
    theme_yellow: String,
    api_base_url: String
}

trait DashboardConfigCl {
    fn clone(&self) -> DashboardConfig;
}

impl DashboardConfigCl for DashboardConfig {
    fn clone(&self) -> DashboardConfig {
        DashboardConfig {
            title: self.title.clone(),
            refresh_interval_sec: self.refresh_interval_sec,
            max_history_rows: self.max_history_rows,
            theme_bg: self.theme_bg.clone(),
            theme_accent: self.theme_accent.clone(),
            theme_pink: self.theme_pink.clone(),
            theme_cyan: self.theme_cyan.clone(),
            theme_orange: self.theme_orange.clone(),
            theme_yellow: self.theme_yellow.clone(),
            api_base_url: self.api_base_url.clone()
        }
    }
}

struct DashboardData {
    deployment_state: DeploymentState,
    aggregated_metrics: AggregatedMetrics,
    recent_history: Vec<ExecutionRecord>,
    pipeline_health: f32
}

trait DashboardDataCl {
    fn clone(&self) -> DashboardData;
}

impl DashboardDataCl for DashboardData {
    fn clone(&self) -> DashboardData {
        let mut cloned_history = vec![];
        for i in 0..self.recent_history.len() {
            cloned_history.push(self.recent_history[i].clone());
        }

        DashboardData {
            deployment_state: self.deployment_state.clone(),
            aggregated_metrics: self.aggregated_metrics.clone(),
            recent_history: cloned_history,
            pipeline_health: self.pipeline_health
        }
    }
}

// ===== Dashboard Configuration =====

fn create_dashboard_config() -> DashboardConfig {
    DashboardConfig {
        title: "Sovereign Workspace v5.0".to_string(),
        refresh_interval_sec: 5i32,
        max_history_rows: 10i32,
        theme_bg: "#282a36".to_string(),
        theme_accent: "#50fa7b".to_string(),
        theme_pink: "#ff79c6".to_string(),
        theme_cyan: "#8be9fd".to_string(),
        theme_orange: "#ffb86c".to_string(),
        theme_yellow: "#f1fa8c".to_string(),
        api_base_url: "http://localhost:8080".to_string()
    }
}

