// Phase 5 Tests
// HTTP Server + Dashboard + Deployment + Metrics

use crate::phase5::metrics_api::*;
use crate::phase5::deployment_manager::*;
use crate::phase5::dashboard::*;
use crate::phase5::http_server::*;

// ===== Group A: HTTP Response Structure (5 tests) =====

test "http_health_response_is_json" {
    let req = HttpRequest {
        method: "GET".to_string(),
        path: "/health".to_string(),
        query_string: "".to_string(),
        body: "".to_string(),
        content_type: "".to_string()
    };
    let server = create_http_server();
    let (resp, _new_server) = handle_health(req, server);
    assert resp.status_code == 200i32;
    assert resp.content_type == "application/json".to_string();
    assert resp.body.len() > 0;
}

test "http_not_found_returns_404" {
    let req = HttpRequest {
        method: "GET".to_string(),
        path: "/unknown".to_string(),
        query_string: "".to_string(),
        body: "".to_string(),
        content_type: "".to_string()
    };
    let server = create_http_server();
    let (resp, _new_server) = handle_not_found(req, server);
    assert resp.status_code == 404i32;
}

test "http_dashboard_returns_html" {
    let req = HttpRequest {
        method: "GET".to_string(),
        path: "/dashboard".to_string(),
        query_string: "".to_string(),
        body: "".to_string(),
        content_type: "".to_string()
    };
    let server = create_http_server();
    let (resp, _new_server) = handle_dashboard(req, server);
    assert resp.content_type == "text/html".to_string();
    assert resp.body.len() > 100i32;
}

test "http_metrics_response_structure" {
    let req = HttpRequest {
        method: "GET".to_string(),
        path: "/metrics".to_string(),
        query_string: "".to_string(),
        body: "".to_string(),
        content_type: "".to_string()
    };
    let server = create_http_server();
    let (resp, _new_server) = handle_metrics(req, server);
    assert resp.status_code == 200i32;
    assert resp.content_type == "application/json".to_string();
}

test "http_history_endpoint_works" {
    let req = HttpRequest {
        method: "GET".to_string(),
        path: "/history".to_string(),
        query_string: "".to_string(),
        body: "".to_string(),
        content_type: "".to_string()
    };
    let server = create_http_server();
    let (resp, _new_server) = handle_history(req, server);
    assert resp.status_code == 200i32;
    assert resp.content_type == "application/json".to_string();
}

// ===== Group B: JSON Serialization (4 tests) =====

test "pipeline_result_json_contains_success_field" {
    let store = create_metrics_store();
    let result = run_agent_pipeline("더하기 5 10".to_string());
    let json = pipeline_result_to_json(result);
    assert json.contains("\"success\"");
    assert json.contains("\"patches_applied\"");
}

test "pipeline_result_json_contains_healing_rate" {
    let result = run_agent_pipeline("변환 hello".to_string());
    let json = pipeline_result_to_json(result);
    assert json.contains("\"healing_success_rate\"");
    assert json.contains("\"learning_rate\"");
}

test "aggregated_metrics_json_structure" {
    let store = create_metrics_store();
    let json = get_metrics_json(store);
    assert json.contains("\"total_executions\"");
    assert json.contains("\"success_count\"");
}

test "complex_scenario_json_structure" {
    let scenario = run_complex_scenario();
    let json = complex_scenario_to_json(scenario);
    assert json.contains("\"scenario_id\"");
    assert json.contains("\"total_success_rate\"");
}

// ===== Group C: Metrics Aggregation (4 tests) =====

test "metrics_store_creation" {
    let store = create_metrics_store();
    assert store.records.len() == 0i32;
    assert store.next_id == 1i32;
}

test "metrics_store_add_record" {
    let mut store = create_metrics_store();
    let result = run_agent_pipeline("테스트".to_string());
    store = add_execution_record(store, result);
    assert store.records.len() == 1i32;
    assert store.next_id == 2i32;
}

test "aggregated_metrics_calculation" {
    let mut store = create_metrics_store();
    let r1 = run_agent_pipeline("더하기 1 2".to_string());
    let r2 = run_agent_pipeline("변환 abc".to_string());
    store = add_execution_record(store, r1);
    store = add_execution_record(store, r2);
    let metrics = calculate_aggregated_metrics(store);
    assert metrics.total_executions == 2i32;
    assert metrics.success_count >= 0i32;
}

test "recent_records_limit" {
    let mut store = create_metrics_store();
    for _i in 0..5 {
        let r = run_agent_pipeline("반복".to_string());
        store = add_execution_record(store, r);
    }
    let recent = get_recent_records(store, 3i32);
    assert recent.len() == 3i32;
}

