   130→        agent_name: "evolution-tracker".to_string(),
   131→        status: "ACTIVE".to_string(),
   132→        last_execution: "2026-03-18T12:00:00Z".to_string(),
   133→        success_rate: 0.99f32,
   134→        total_executions: 10i32
   135→    });
   136→
   137→    statuses
   138→}
   139→
   140→fn update_agent_status(state: DeploymentState, agent_name: String, success: bool) -> DeploymentState {
   141→    let mut updated_agents = vec![];
   142→
   143→    for i in 0..state.agent_statuses.len() {
   144→        let agent = &state.agent_statuses[i];
   145→        if agent.agent_name == agent_name {
   146→            let total = agent.total_executions + 1;
   147→            let success_count = if success {
   148→                (agent.success_rate * (agent.total_executions as f32)) as i32 + 1
   149→            } else {
   150→                (agent.success_rate * (agent.total_executions as f32)) as i32
   151→            };
   152→            let new_rate = (success_count as f32) / (total as f32);
   153→
   154→            updated_agents.push(AgentStatus {
   155→                agent_name: agent.agent_name.clone(),
   156→                status: "ACTIVE".to_string(),
   157→                last_execution: "2026-03-18T12:00:00Z".to_string(),
   158→                success_rate: new_rate,
   159→                total_executions: total
   160→            });
   161→        } else {
   162→            updated_agents.push(agent.clone());
   163→        }
   164→    }
   165→
   166→    DeploymentState {
   167→        service_info: state.service_info.clone(),
   168→        agent_statuses: updated_agents,
   169→        is_healthy: state.is_healthy,
   170→        pipeline_health: state.pipeline_health,
   171→        total_pipeline_runs: state.total_pipeline_runs
   172→    }
   173→}
   174→
   175→fn increment_pipeline_runs(state: DeploymentState) -> DeploymentState {
   176→    DeploymentState {
   177→        service_info: state.service_info.clone(),
   178→        agent_statuses: state.agent_statuses.clone(),
   179→        is_healthy: state.is_healthy,
   180→        pipeline_health: state.pipeline_health,
   181→        total_pipeline_runs: state.total_pipeline_runs + 1
   182→    }
   183→}
   184→
   185→fn refresh_pipeline_health(state: DeploymentState) -> DeploymentState {
   186→    let mut total_rate = 0.0f32;
   187→    for i in 0..state.agent_statuses.len() {
   188→        total_rate = total_rate + state.agent_statuses[i].success_rate;
   189→    }
   190→    let avg_health = total_rate / (state.agent_statuses.len() as f32);
   191→
   192→    DeploymentState {
   193→        service_info: state.service_info.clone(),
   194→        agent_statuses: state.agent_statuses.clone(),
   195→        is_healthy: avg_health > 0.9f32,
   196→        pipeline_health: avg_health,
   197→        total_pipeline_runs: state.total_pipeline_runs
   198→    }
   199→}
