// Phase 8: Tenant Context
// 요청 컨텍스트 및 테넌트 인증 정보

use crate::phase5::http_server::*;

struct TenantContext {
    tenant_id: String,
    request_id: String,
    timestamp: String,
    user_agent: String,
    is_authenticated: bool
}

trait TenantContextCl {
    fn clone(&self) -> TenantContext;
}

impl TenantContextCl for TenantContext {
    fn clone(&self) -> TenantContext {
        TenantContext {
            tenant_id: self.tenant_id.clone(),
            request_id: self.request_id.clone(),
            timestamp: self.timestamp.clone(),
            user_agent: self.user_agent.clone(),
            is_authenticated: self.is_authenticated.clone()
        }
    }
}

// 요청에서 테넌트 컨텍스트 추출
fn extract_tenant_context(req: HttpRequest) -> TenantContext {
    // query_string 또는 request body에서 X-Tenant-ID 파싱
    let tenant_id = if req.query_string.contains("tenant_id=") {
        // 간단한 파싱: "tenant_id=xxx" 형태
        let parts: Vec<String> = req.query_string.split("=").map(|s| s.to_string()).collect();
        if parts.len() > 1 {
            parts[1].clone()
        } else {
            "".to_string()
        }
    } else {
        "".to_string()
    };

    let is_auth = tenant_id.len() > 0i32;

    TenantContext {
        tenant_id: tenant_id,
        request_id: "req-001".to_string(),
        timestamp: "2026-03-18T12:00:00Z".to_string(),
        user_agent: "Mozilla/5.0".to_string(),
        is_authenticated: is_auth
    }
}

// 익명 컨텍스트 생성 (게스트)
fn create_anonymous_context() -> TenantContext {
    TenantContext {
        tenant_id: "anonymous".to_string(),
        request_id: "req-guest-001".to_string(),
        timestamp: "2026-03-18T12:00:00Z".to_string(),
        user_agent: "Mozilla/5.0".to_string(),
        is_authenticated: false
    }
}

// 컨텍스트 유효성 확인
fn is_context_valid(ctx: TenantContext) -> bool {
    ctx.is_authenticated && ctx.tenant_id.len() > 0i32
}

// 컨텍스트를 JSON으로 변환
fn context_to_json(ctx: TenantContext) -> String {
    let mut json = String::new();
    json.push_str("{\"tenant_id\":\"");
    json.push_str(ctx.tenant_id.as_str());
    json.push_str("\",\"request_id\":\"");
    json.push_str(ctx.request_id.as_str());
    json.push_str("\",\"timestamp\":\"");
    json.push_str(ctx.timestamp.as_str());
    json.push_str("\",\"is_authenticated\":");
    json.push_str(if ctx.is_authenticated { "true" } else { "false" });
    json.push_str("}");
    json
}

