    let mut json = String::new();
    json.push_str("{\"tenant_id\":\"");
    json.push_str(quota.tenant_id.as_str());
    json.push_str("\",\"max_pipeline_runs\":");
    json.push_str(&quota.max_pipeline_runs.to_string());
    json.push_str(",\"used_pipeline_runs\":");
    json.push_str(&quota.used_pipeline_runs.to_string());
    json.push_str(",\"max_storage_mb\":");
    json.push_str(&quota.max_storage_mb.to_string());
    json.push_str(",\"used_storage_mb\":");
    json.push_str(&quota.used_storage_mb.to_string());
    json.push_str(",\"usage_percentage\":");
    json.push_str(&get_usage_percentage(quota).to_string());
    json.push_str("}");
    json
}

