    status: String,                  // "active", "inactive", "suspended"
    quota: ResourceQuota
}

trait TenantCl {
    fn clone(&self) -> Tenant;
}

impl TenantCl for Tenant {
    fn clone(&self) -> Tenant {
        Tenant {
            tenant_id: self.tenant_id.clone(),
            name: self.name.clone(),
            api_key: self.api_key.clone(),
            created_at: self.created_at.clone(),
            status: self.status.clone(),
            quota: self.quota.clone()
        }
    }
}

struct TenantManager {
    tenants: Vec<Tenant>,
    active_count: i32,
    next_tenant_num: i32
}

trait TenantManagerCl {
    fn clone(&self) -> TenantManager;
}

impl TenantManagerCl for TenantManager {
    fn clone(&self) -> TenantManager {
        let mut cloned_tenants = vec![];
        let mut i = 0i32;
        loop {
            if i >= (self.tenants.len() as i32) { break; }
            cloned_tenants.push(self.tenants[(i as usize)].clone());
            i = i + 1i32;
        }

        TenantManager {
            tenants: cloned_tenants,
            active_count: self.active_count.clone(),
            next_tenant_num: self.next_tenant_num.clone()
        }
    }
}

// 테넌트 매니저 생성
fn create_tenant_manager() -> TenantManager {
    TenantManager {
        tenants: vec![],
        active_count: 0i32,
        next_tenant_num: 1i32
    }
}

// 테넌트 생성
fn create_tenant(name: String, api_key: String) -> Tenant {
    let tenant_id = "tenant-001".to_string();
    let quota = create_resource_quota(tenant_id.clone());

    Tenant {
        tenant_id: tenant_id,
        name: name,
        api_key: api_key,
        created_at: "2026-03-18T12:00:00Z".to_string(),
        status: "active".to_string(),
        quota: quota
    }
}

// 테넌트 추가
fn add_tenant(manager: TenantManager, tenant: Tenant) -> TenantManager {
    let mut new_tenants = vec![];
    let mut i = 0i32;
    loop {
        if i >= (manager.tenants.len() as i32) { break; }
        new_tenants.push(manager.tenants[(i as usize)].clone());
        i = i + 1i32;
    }
    new_tenants.push(tenant);

    TenantManager {
        tenants: new_tenants,
        active_count: manager.active_count + 1i32,
        next_tenant_num: manager.next_tenant_num + 1i32
    }
}

// API 키로 테넌트 ID 찾기
fn find_tenant_by_key(manager: TenantManager, api_key: String) -> String {
    let mut i = 0i32;
    loop {
        if i >= (manager.tenants.len() as i32) { break; }
        let tenant = manager.tenants[(i as usize)].clone();
        if tenant.api_key == api_key {
            return tenant.tenant_id;
        }
        i = i + 1i32;
    }
    "".to_string()
}

// 테넌트 ID로 테넌트 조회
fn get_tenant_by_id(manager: TenantManager, tenant_id: String) -> String {
    let mut i = 0i32;
    loop {
        if i >= (manager.tenants.len() as i32) { break; }
        let tenant = manager.tenants[(i as usize)].clone();
        if tenant.tenant_id == tenant_id {
            return tenant_to_json(tenant);
        }
        i = i + 1i32;
    }
    "{}".to_string()
}

// 테넌트를 JSON으로 변환
fn tenant_to_json(tenant: Tenant) -> String {
    let mut json = String::new();
    json.push_str("{\"tenant_id\":\"");
    json.push_str(tenant.tenant_id.as_str());
    json.push_str("\",\"name\":\"");
    json.push_str(tenant.name.as_str());
    json.push_str("\",\"status\":\"");
    json.push_str(tenant.status.as_str());
    json.push_str("\",\"quota\":");
    json.push_str(quota_to_json(tenant.quota).as_str());
    json.push_str("}");
    json
}

// 테넌트 비활성화
fn deactivate_tenant(manager: TenantManager, tenant_id: String) -> TenantManager {
    let mut new_tenants = vec![];
    let mut new_active = manager.active_count;
    let mut i = 0i32;
    loop {
        if i >= (manager.tenants.len() as i32) { break; }
        let mut tenant = manager.tenants[(i as usize)].clone();
        if tenant.tenant_id == tenant_id && tenant.status == "active".to_string() {
            tenant = Tenant {
                tenant_id: tenant.tenant_id.clone(),
                name: tenant.name.clone(),
                api_key: tenant.api_key.clone(),
                created_at: tenant.created_at.clone(),
                status: "inactive".to_string(),
                quota: tenant.quota.clone()
            };
            new_active = new_active - 1i32;
        }
        new_tenants.push(tenant);
        i = i + 1i32;
    }

    TenantManager {
        tenants: new_tenants,
        active_count: new_active,
        next_tenant_num: manager.next_tenant_num
    }
}

// 활성 테넌트 목록을 JSON으로 반환
fn list_active_tenants_json(manager: TenantManager) -> String {
    let mut json = String::new();
    json.push_str("[");
    let mut first = true;
    let mut i = 0i32;
    loop {
        if i >= (manager.tenants.len() as i32) { break; }
        let tenant = manager.tenants[(i as usize)].clone();
        if tenant.status == "active".to_string() {
            if !first {
                json.push_str(",");
            }
            json.push_str(tenant_to_json(tenant).as_str());
            first = false;
        }
        i = i + 1i32;
    }
    json.push_str("]");
    json
}

// 테넌트 수 조회
fn get_tenant_count(manager: TenantManager) -> i32 {
    manager.tenants.len() as i32
}

