    let manager = create_db_manager(config);
    assert manager.is_connected;
    assert manager.total_queries == 0i32;
}

test "db_manager_execute_query_increments_count" {
    let config = create_db_config("test.db".to_string());
    let manager = create_db_manager(config);

    let (result, m2) = execute_query(manager, "SELECT * FROM test".to_string());
    assert m2.total_queries == 1i32;
}

test "db_manager_transaction_tracking" {
    let config = create_db_config("test.db".to_string());
    let manager = create_db_manager(config);

    let m2 = begin_transaction(manager);
    assert m2.active_transactions == 1i32;

    let m3 = commit_transaction(m2);
    assert m3.active_transactions == 0i32;
}

