        is_listening: server.is_listening,
        total_requests: server.total_requests + 1i32,
        total_errors: server.total_errors
    };

    (response, new_server)
}

// Health Check RPC 처리
fn handle_health_check(server: GrpcServer, req: HealthCheckRequest) -> (HealthCheckResponse, GrpcServer) {
    let mut service_found = false;
    let mut i = 0i32;
    loop {
        if i >= (server.services.len() as i32) { break; }
        let service = server.services[(i as usize)].clone();
        if service.service_name == req.service_name && service.tenant_id == req.tenant_id {
            service_found = true;
        }
        i = i + 1i32;
    }

    let status = if service_found { "SERVING".to_string() } else { "NOT_SERVING".to_string() };

    let response = HealthCheckResponse {
        service_name: req.service_name.clone(),
        status: status,
        uptime_seconds: 3600i32,
        last_check: "2026-03-18T12:00:00Z".to_string()
    };

    let new_server = GrpcServer {
        services: server.services.clone(),
        tenant_manager: server.tenant_manager.clone(),
        port: server.port,
        is_listening: server.is_listening,
        total_requests: server.total_requests + 1i32,
        total_errors: server.total_errors
    };

    (response, new_server)
}

// 서버 시작
fn start_grpc_server(server: GrpcServer) -> GrpcServer {
    GrpcServer {
        services: server.services.clone(),
        tenant_manager: server.tenant_manager.clone(),
        port: server.port,
        is_listening: true,
        total_requests: server.total_requests,
        total_errors: server.total_errors
    }
}

// 서버 통계 조회
fn get_grpc_server_stats(server: GrpcServer) -> String {
    let mut json = String::new();
    json.push_str("{\"port\":");
    json.push_str(&server.port.to_string());
    json.push_str(",\"is_listening\":");
    if server.is_listening {
        json.push_str("true");
    } else {
        json.push_str("false");
    }
    json.push_str(",\"total_requests\":");
    json.push_str(&server.total_requests.to_string());
    json.push_str(",\"total_errors\":");
    json.push_str(&server.total_errors.to_string());
    json.push_str(",\"service_count\":");
    json.push_str(&(server.services.len() as i32).to_string());
    json.push_str("}");
    json
}

// 서비스 목록 조회
fn list_grpc_services(server: GrpcServer) -> String {
    let mut json = String::new();
    json.push_str("[");
    let mut first = true;
    let mut i = 0i32;
    loop {
        if i >= (server.services.len() as i32) { break; }
        let service = server.services[(i as usize)].clone();
        if !first {
            json.push_str(",");
        }
        json.push_str("{\"service_name\":\"");
        json.push_str(service.service_name.as_str());
        json.push_str("\",\"tenant_id\":\"");
        json.push_str(service.tenant_id.as_str());
        json.push_str("\",\"is_running\":");
        if service.is_running {
            json.push_str("true");
        } else {
            json.push_str("false");
        }
        json.push_str("}");
        first = false;
        i = i + 1i32;
    }
    json.push_str("]");
    json
}

// 진입점
fn run_grpc_server() {
    println!("Sovereign Workspace Phase 9: gRPC Server");
    println!("Listening on port 50051");
    println!("Services:");
    println!("  - PipelineService");
    println!("  - MetricsService");
    println!("  - HealthCheckService");
}

