// Phase 9: gRPC 마이크로서비스 테스트 (15개)

use crate::phase9::proto_definitions::*;
use crate::phase9::grpc_server::*;
use crate::phase9::grpc_client::*;
use crate::phase9::service_registry::*;
use crate::phase8::tenant_manager::*;

// ===== Group A: Protocol Definitions (3개) =====

test "pipeline_request_creation_sets_fields" {
    let req = create_pipeline_request(
        "req-001".to_string(),
        "tenant-123".to_string(),
        "test intent".to_string()
    );
    assert req.request_id == "req-001".to_string();
    assert req.tenant_id == "tenant-123".to_string();
    assert req.user_intent == "test intent".to_string();
}

test "pipeline_response_to_json_contains_all_fields" {
    let resp = create_pipeline_response(
        "resp-001".to_string(),
        "tenant-123".to_string(),
        true,
        125i32,
        "success".to_string()
    );
    let json = pipeline_response_to_json(resp);
    assert json.contains("response_id");
    assert json.contains("tenant_id");
    assert json.contains("success");
}

test "metrics_response_serialization_valid" {
    let resp = create_metrics_response(
        "resp-002".to_string(),
        "tenant-123".to_string(),
        "execution_time".to_string(),
        98.5f32
    );
    let json = metrics_response_to_json(resp);
    assert json.contains("metric_type");
    assert json.contains("value");
}

// ===== Group B: gRPC Server (4개) =====

test "grpc_server_creation_initializes_empty" {
    let server = create_grpc_server(50051i32);
    assert server.port == 50051i32;
    assert server.is_listening == false;
    assert server.total_requests == 0i32;
}

test "grpc_server_register_service_increments_count" {
    let server = create_grpc_server(50051i32);
    let s2 = register_service(server, "PipelineService".to_string(), "tenant-1".to_string());
    assert s2.services.len() as i32 > 0i32;
}

test "grpc_server_start_sets_listening" {
    let server = create_grpc_server(50051i32);
    let s2 = start_grpc_server(server);
    assert s2.is_listening;
}

test "grpc_server_pipeline_call_with_valid_tenant" {
    let mut server = create_grpc_server(50051i32);
    let tenant = create_tenant("TestCo".to_string(), "key-abc".to_string());
    let manager = add_tenant(create_tenant_manager(), tenant);
    server = GrpcServer {
        services: server.services.clone(),
        tenant_manager: manager,
        port: server.port,
        is_listening: server.is_listening,
        total_requests: server.total_requests,
        total_errors: server.total_errors
    };

    let req = create_pipeline_request(
        "req-001".to_string(),
        "tenant-001".to_string(),
        "test".to_string()
    );
    let (resp, s2) = handle_pipeline_call(server, req);
    assert s2.total_requests == 1i32;
}

// ===== Group C: gRPC Client (4개) =====

test "grpc_client_creation_initializes_connection" {
    let client = create_grpc_client(
        "localhost".to_string(),
        50051i32,
        "tenant-1".to_string(),
