// Phase 10: 고급 분석 테스트 (20개)

use crate::phase10::metrics_aggregator::*;
use crate::phase10::timeseries_storage::*;
use crate::phase10::analytics_dashboard::*;

// ===== Group A: Metrics Aggregator (4개) =====

test "metrics_aggregator_creation_empty" {
    let agg = create_metrics_aggregator();
    assert agg.total_points == 0i32;
}

test "metrics_aggregator_add_data_point_increments_count" {
    let agg = create_metrics_aggregator();
    let a2 = add_data_point(agg, "execution_time".to_string(), 125.0f32, "tenant-1".to_string());
    assert a2.total_points == 1i32;
}

test "metrics_aggregator_aggregate_calculates_min_max_avg" {
    let agg = create_metrics_aggregator();
    let a2 = add_data_point(agg, "execution_time".to_string(), 100.0f32, "tenant-1".to_string());
    let a3 = add_data_point(a2, "execution_time".to_string(), 200.0f32, "tenant-1".to_string());

    let metrics = aggregate_metrics(a3, "execution_time".to_string(), "tenant-1".to_string());
    assert metrics.count == 2i32;
    assert metrics.min_value == 100.0f32;
    assert metrics.max_value == 200.0f32;
}

test "aggregated_metrics_to_json_contains_stats" {
    let metrics = AggregatedMetrics {
        tenant_id: "tenant-1".to_string(),
        metric_name: "execution_time".to_string(),
        min_value: 100.0f32,
        max_value: 200.0f32,
        avg_value: 150.0f32,
        sum_value: 300.0f32,
        count: 2i32,
        last_updated: "2026-03-18T12:00:00Z".to_string()
    };
    let json = aggregated_metrics_to_json(metrics);
    assert json.contains("min");
    assert json.contains("max");
    assert json.contains("avg");
}

// ===== Group B: TimeSeries Storage (4개) =====

test "timeseries_db_creation_sets_retention" {
    let db = create_timeseries_db("tenant-1".to_string(), 30i32);
    assert db.tenant_id == "tenant-1".to_string();
    assert db.retention_days == 30i32;
    assert db.total_entries == 0i32;
}

test "timeseries_write_entry_increments_count" {
    let db = create_timeseries_db("tenant-1".to_string(), 30i32);
    let d2 = write_timeseries_entry(
        db,
        "2026-03-18T12:00:00Z".to_string(),
        "execution_time".to_string(),
        125.0f32
    );
    assert d2.total_entries == 1i32;
    assert d2.next_entry_id == 2i32;
}

test "timeseries_query_returns_matching_entries" {
    let db = create_timeseries_db("tenant-1".to_string(), 30i32);
    let d2 = write_timeseries_entry(
        db,
        "2026-03-18T12:00:00Z".to_string(),
        "execution_time".to_string(),
        125.0f32
    );

    let query = TimeSeriesQuery {
        metric_name: "execution_time".to_string(),
        start_time: "2026-03-18T00:00:00Z".to_string(),
        end_time: "2026-03-18T23:59:59Z".to_string(),
        tenant_id: "tenant-1".to_string(),
        limit: 10i32
    };

    let result = query_timeseries(d2, query);
    assert result.result_count == 1i32;
}

test "timeseries_get_latest_entries_limits_results" {
    let db = create_timeseries_db("tenant-1".to_string(), 30i32);
    let d2 = write_timeseries_entry(db, "2026-03-18T12:00:00Z".to_string(), "metric".to_string(), 100.0f32);
    let d3 = write_timeseries_entry(d2, "2026-03-18T12:05:00Z".to_string(), "metric".to_string(), 110.0f32);

    let latest = get_latest_entries(d3, "metric".to_string(), 1i32);
    assert latest.len() as i32 <= 1i32;
}

// ===== Group C: Analytics Dashboard (6개) =====

test "dashboard_creation_initializes_empty" {
    let dash = create_dashboard("tenant-1".to_string());
    assert dash.tenant_id == "tenant-1".to_string();
    assert dash.widget_count == 0i32;
    assert dash.is_live;
}

test "dashboard_add_widget_increments_count" {
    let dash = create_dashboard("tenant-1".to_string());
    let d2 = add_widget(dash, "chart".to_string(), "execution_time".to_string(), "Execution Time".to_string());
    assert d2.widget_count == 1i32;
}

test "dashboard_to_json_contains_metadata" {
    let dash = create_dashboard("tenant-1".to_string());
    let json = dashboard_to_json(dash);
    assert json.contains("dashboard_id");
    assert json.contains("widget_count");
}

test "analytics_report_generation_sets_period" {
    let report = generate_analytics_report("tenant-1".to_string(), "daily".to_string());
    assert report.report_type == "daily".to_string();
    assert report.period_start.len() > 0i32;
}

test "analytics_report_add_metric_increments_count" {
    let report = generate_analytics_report("tenant-1".to_string(), "daily".to_string());
    let r2 = add_metric_to_report(report, "avg_execution_time: 125ms".to_string());
    assert r2.metrics_summary.len() as i32 == 1i32;
}

test "report_to_json_contains_report_info" {
    let report = generate_analytics_report("tenant-1".to_string(), "weekly".to_string());
    let json = report_to_json(report);
    assert json.contains("report_type");
    assert json.contains("metrics_count");
}

// ===== Group D: Alerts (4개) =====

test "analytics_alert_creation_sets_fields" {
    let alert = create_analytics_alert(
        "tenant-1".to_string(),
        "execution_time".to_string(),
        500.0f32,
        ">".to_string(),
        "warning".to_string()
    );
    assert alert.metric_name == "execution_time".to_string();
    assert alert.threshold == 500.0f32;
    assert alert.is_active;
}

test "analytics_alert_check_triggers_on_threshold" {
    let alert = create_analytics_alert(
        "tenant-1".to_string(),
        "execution_time".to_string(),
        500.0f32,
        ">".to_string(),
        "warning".to_string()
    );

    let (triggered, a2) = check_alert(alert, 600.0f32);
    assert triggered;
    assert a2.last_triggered.len() > 0i32;
}

test "analytics_alert_check_not_triggers_below_threshold" {
    let alert = create_analytics_alert(
        "tenant-1".to_string(),
        "execution_time".to_string(),
        500.0f32,
        ">".to_string(),
        "warning".to_string()
    );

    let (triggered, a2) = check_alert(alert, 300.0f32);
    assert !triggered;
}

test "alert_to_json_contains_threshold" {
    let alert = create_analytics_alert(
        "tenant-1".to_string(),
        "error_rate".to_string(),
        5.0f32,
        "<".to_string(),
        "critical".to_string()
    );
    let json = alert_to_json(alert);
    assert json.contains("threshold");
    assert json.contains("severity");
}

// ===== Group E: Integration (2개) =====

test "full_analytics_pipeline_aggregator_to_dashboard" {
    let agg = create_metrics_aggregator();
    let a2 = add_data_point(agg, "execution_time".to_string(), 125.0f32, "tenant-1".to_string());

    let dash = create_dashboard("tenant-1".to_string());
    let d2 = add_widget(dash, "chart".to_string(), "execution_time".to_string(), "Execution Time".to_string());

    assert a2.total_points == 1i32;
    assert d2.widget_count == 1i32;
}

test "timeseries_to_alert_workflow" {
    let db = create_timeseries_db("tenant-1".to_string(), 30i32);
    let d2 = write_timeseries_entry(db, "2026-03-18T12:00:00Z".to_string(), "error_rate".to_string(), 8.5f32);

    let alert = create_analytics_alert(
        "tenant-1".to_string(),
        "error_rate".to_string(),
        5.0f32,
        ">".to_string(),
        "critical".to_string()
    );

    let (triggered, a2) = check_alert(alert, 8.5f32);
    assert triggered;
    assert d2.total_entries == 1i32;
}

