use crate::phase11::model_tuner::*;
use crate::phase11::autoscaler::*;
use crate::phase11::performance_predictor::*;

// ===== Group A: Model Tuner (5개) =====

test "model_tuner_creation_initializes_empty" {
    let tuner = create_model_tuner("tenant-1".to_string());
    assert tuner.tenant_id == "tenant-1".to_string();
    assert tuner.optimization_score == 0.0f32;
}

test "model_tuner_add_performance_metric" {
    let tuner = create_model_tuner("tenant-1".to_string());
    let t2 = add_performance_metric(
        tuner,
        "execution_time".to_string(),
        150.0f32,
        100.0f32
    );
    assert t2.metrics.len() as i32 == 1i32;
}

test "model_tuner_add_tuning_parameter" {
    let tuner = create_model_tuner("tenant-1".to_string());
    let t2 = add_tuning_parameter(
        tuner,
        "connection_pool_size".to_string(),
        50.0f32,
        10.0f32,
        200.0f32,
        "high".to_string()
    );
    assert t2.parameters.len() as i32 == 1i32;
}

test "model_tuner_generate_recommendation" {
    let tuner = create_model_tuner("tenant-1".to_string());
    let t2 = add_tuning_parameter(
        tuner,
        "cache_size".to_string(),
        1024.0f32,
        256.0f32,
        8192.0f32,
        "high".to_string()
    );

    let rec = generate_tuning_recommendation(
        t2,
        "cache_size".to_string(),
        2048.0f32,
        15.0f32
    );
    assert rec.param_name == "cache_size".to_string();
    assert rec.expected_improvement == 15.0f32;
}

test "model_tuner_apply_recommendation" {
    let tuner = create_model_tuner("tenant-1".to_string());
    let t2 = add_tuning_parameter(
        tuner,
        "batch_size".to_string(),
        32.0f32,
        8.0f32,
        256.0f32,
        "medium".to_string()
    );

    let rec = TuningRecommendation {
        recommendation_id: "rec-test".to_string(),
        param_name: "batch_size".to_string(),
        current_value: 32.0f32,
        recommended_value: 64.0f32,
        expected_improvement: 10.0f32,
        confidence_score: 0.88f32,
        reason: "Performance analysis".to_string()
    };

    let t3 = apply_tuning_recommendation(t2, rec);
    assert t3.tuning_history.len() as i32 > 0i32;
}

