        scaler,
        "cpu_usage".to_string(),
        65.0f32,
        100.0f32
    );
    assert s2.resource_metrics.len() as i32 == 1i32;
}

test "autoscaler_evaluate_scaling_up" {
    let scaler = create_autoscaler("tenant-1".to_string(), 2i32, 10i32);
    let s2 = add_resource_metric(
        scaler,
        "memory_usage".to_string(),
        85.0f32,
        100.0f32
